package com.medtrack.inventory.dto; import com.medtrack.inventory.entity.InventoryJournalEntry; import java.time.Instant; import java.util.*; public record JournalEntryResponse(UUID id,String entryNumber,String entryType,String referenceEntityType,UUID referenceEntityId,String description,Instant createdAt,int lineCount){public static JournalEntryResponse of(InventoryJournalEntry entry){return new JournalEntryResponse(entry.getId(),entry.getEntryNumber(),entry.getEntryType().name(),entry.getReferenceEntityType(),entry.getReferenceEntityId(),entry.getDescription(),entry.getCreatedAt(),entry.getLines().size());}}
